import json, hashlib
from collections import Counter
from datetime import datetime
from pathlib import Path
for filename in ('regras.md', 'eventos.json'):
    print(filename, 'sha256', hashlib.sha256(Path(filename).read_bytes()).hexdigest())
events = json.loads(Path('eventos.json').read_text())
unique = {}
for e in events:
    if e['event_id'] in unique:
        assert unique[e['event_id']] == e, 'Duplicata conflitante'
    else:
        unique[e['event_id']] = e
start = datetime.fromisoformat('2026-10-10T00:00:00+00:00')
end = datetime.fromisoformat('2026-10-11T00:00:00+00:00')
def instant(e):
    return datetime.fromisoformat(e['em'].replace('Z', '+00:00'))
payments = [e for e in unique.values() if e['tipo'] == 'pago' and e['moeda'] == 'BRL' and start <= instant(e) < end]
channels = {'loja': 0, 'web': 0}
for payment in sorted(payments, key=lambda e: e['pedido']):
    refunds = [e for e in unique.values() if e['pedido'] == payment['pedido'] and e['tipo'] == 'estorno_confirmado' and instant(e) < end]
    net = payment['valor'] - sum(e['valor'] for e in refunds)
    channels[payment['canal']] += net
    print(json.dumps({'pedido': payment['pedido'], 'pagamento': payment['event_id'], 'bruto': payment['valor'], 'estornos': [e['event_id'] for e in refunds], 'liquido': net, 'canal': payment['canal']}))
print('Duplicatas:', {k: v for k, v in Counter(e['event_id'] for e in events).items() if v > 1})
print(json.dumps({'pedidos_incluidos': sorted(e['pedido'] for e in payments), 'receita_liquida_centavos': sum(channels.values()), 'por_canal_centavos': channels}, ensure_ascii=False))
